205	// UseTimezone converts last login date to the given timezone.
206	// @effects: mut
207	func (u *User) UseTimezone(tz string) {
208		if u.LastLoginAt != nil {
209			*u.LastLoginAt = timezone.Convert(tz, *u.LastLoginAt)
210		}
211	}
212	
213	// Users represents a list of users.
214	type Users []*User
215	
216	// UseTimezone converts last login timestamp of all users to the given timezone.
217	// @effects: mut
218	func (u Users) UseTimezone(tz string) {
219		for _, user := range u {
220			user.UseTimezone(tz)
221		}
