169	// @effects: reads users
170	func (h *handler) usersHandler(w http.ResponseWriter, r *http.Request) {
171		if !request.IsAdminUser(r) {
172			response.JSONForbidden(w, r)
173			return
174		}
175	
176		users, err := h.store.Users()
