251	func (h *handler) removeUserHandler(w http.ResponseWriter, r *http.Request) {
252		if !request.IsAdminUser(r) {
253			response.JSONForbidden(w, r)
254			return
255		}
256	
257		userID := request.RouteInt64Param(r, "userID")
258		if userID == 0 {
259			response.JSONBadRequest(w, r, errors.New("invalid user ID"))
260			return
261		}
